import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`shopify-international`,heroTitle:`Take your Shopify store international in minutes`,heroSubtitle:`Perplexity Computer audits your store, ranks market readiness, and builds your expansion plan — automatically.`,inputUrlCta:`Audit my store`,inputUrlPlaceholder:`yourstore.myshopify.com`,inputUrlPrefill:`Go to {url} and do a full international readiness audit of this Shopify store. Check the following: 1) Multi-currency setup and payment gateway support for international transactions. 2) Language support and translation coverage. 3) Hreflang tags and international SEO configuration. 4) International shipping options, zones, and carrier integrations. 5) Tax compliance setup for VAT, GST, and customs duties. 6) Geo-IP detection and redirect configuration. Then rank the store's readiness by target market — UK, EU, APAC, and LATAM — scoring each on a scale of 1-10 with specific gaps to fix. Estimate the addressable market size for each region based on the store's product category. Finally, deliver a prioritized 60-day international expansion plan with concrete action items for each market.`,heroOverlaySteps:[`Crawling your Shopify store for currency, language, and SEO setup`,`Checking hreflang tags, shipping zones, and tax compliance across regions`,`Scoring international readiness for UK, EU, APAC, and LATAM markets`,`Expansion plan, market sizing, and prioritized fixes — ready to execute`],generatingSteps:[`Visiting {url} to map your store's current international configuration`,`Designing an agent to audit multi-currency, language, and geo-IP settings across regions`,`Configuring market readiness scoring for UK, EU, APAC, and LATAM`,`Setting up addressable market estimates and a 60-day expansion roadmap`],featureSectionTitle:`From storefront to global brand`,featureCardTitles:[`Connects to your e-commerce stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Search Console, Stripe, ShipStation, Klaviyo — Computer plugs into your tools so international setup, compliance, and tracking happen in one workflow.`,`Market readiness scorecards. Hreflang tag templates. Shipping zone configurations. Tax compliance checklists. A prioritized 60-day expansion plan with addressable market estimates.`],capabilitySectionTitle:`Your expansion team, on autopilot`,capabilitySectionSubtitle:`Paste your store URL, step away, come back to a complete international strategy.`,capabilityCards:[{title:`Store Audit`,description:`Computer can crawl your entire Shopify store — currency settings, language coverage, hreflang tags, shipping zones — and deliver a prioritized gap analysis.`},{title:`Market Readiness`,description:`Computer can score your readiness for UK, EU, APAC, and LATAM markets and estimate addressable revenue for each region.`},{title:`Compliance Review`,description:`Computer can check your VAT, GST, and customs duty setup against current regulations — and flag what needs fixing before you launch.`},{title:`Connect Your Tools`,description:`Computer can read from Shopify, Stripe, Google Analytics, ShipStation, and more — build workflows across your entire e-commerce stack.`},{title:`Remember & Learn`,description:`Computer can remember your target markets, product catalog, and compliance requirements across sessions — so every audit builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch currency rates, tax regulation changes, and shipping disruptions — and ping you when something affects your international stores.`}]});export{t as default};
